	knownrebecs { 
		PongActor pongRef;
	}
	statevars {
		int id;
	}

	PingActor(PongActor pongRef, int identifier) {
		pongRef = pongRef;
		id = identifier;
	}

	msgsrv start() {
		pongRef.ping(id);
	}

	msgsrv stringMessage() {
		pongRef.ping(id);
	}
}

